FString FCrddPreserveEvidenceOperation::ErrorCode(ECrddPreserveEvidenceError Error)
{
    switch (Error)
    {
    case ECrddPreserveEvidenceError::None:
        return TEXT("");
    case ECrddPreserveEvidenceError::EvidenceHashMismatch:
        return TEXT("EVIDENCE_HASH_MISMATCH");
    case ECrddPreserveEvidenceError::DuplicateFragmentId:
        return TEXT("DUPLICATE_FRAGMENT_ID");
    case ECrddPreserveEvidenceError::DuplicateSegmentId:
        return TEXT("DUPLICATE_SEGMENT_ID");
    default:
        return TEXT("UNKNOWN");
    }
}

bool FCrddPreserveEvidenceOperation::TryParseProjectedInt64(
    const FString& Decimal,
    int64& OutValue
)
{
    if (Decimal.IsEmpty() || Decimal.TrimStartAndEnd() != Decimal)
    {
        return false;
    }
    if (!LexTryParseString(OutValue, *Decimal))
    {
        return false;
    }
    return LexToString(OutValue) == Decimal;
}

FString FCrddPreserveEvidenceOperation::SerializeProjectedInt64(int64 Value)
{
    return LexToString(Value);
}
